-- Seed the six homepage desk stories as published articles so they
-- appear in /admin/articles and remain editable. Static src/data/news.ts
-- stays as a fallback when a slug is missing from the database.

insert into public.articles (
  created_at,
  updated_at,
  published_at,
  status,
  slug,
  title,
  excerpt,
  seo_title,
  seo_description,
  category,
  cover_image_url,
  cover_image_alt,
  author_name,
  author_role,
  author_avatar_url,
  body_markdown
)
